#!/usr/bin/env python3
"""Parse a YAML file and extract nested columns, outputting an HTML table."""

import sys
import yaml


def flatten_columns(data, parent_key="", sep="."):
    """Recursively flatten nested YAML structure into dot-separated column paths."""
    items = []
    if isinstance(data, dict):
        for k, v in data.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, (dict, list)):
                items.extend(flatten_columns(v, new_key, sep))
            else:
                items.append((new_key, v))
    elif isinstance(data, list):
        for i, v in enumerate(data):
            new_key = f"{parent_key}[{i}]"
            if isinstance(v, (dict, list)):
                items.extend(flatten_columns(v, new_key, sep))
            else:
                items.append((new_key, v))
    else:
        items.append((parent_key, data))
    return items


def rows_to_html(columns):
    """Convert a list of (column_path, value) tuples into an HTML table."""
    rows = []
    for path, value in columns:
        escaped_path = path.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
        escaped_val = str(value).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
        rows.append(f"  <tr><td>{escaped_path}</td><td>{escaped_val}</td></tr>")

    return (
        "<!DOCTYPE html>\n"
        "<html><head><meta charset=\"utf-8\"><title>YAML Columns</title>\n"
        "<style>\n"
        "  body { font-family: sans-serif; padding: 2rem; }\n"
        "  table { border-collapse: collapse; width: 100%; max-width: 800px; }\n"
        "  th, td { border: 1px solid #ccc; padding: 0.5rem 1rem; text-align: left; }\n"
        "  th { background: #f5f5f5; }\n"
        "  tr:nth-child(even) { background: #fafafa; }\n"
        "</style>\n"
        "</head><body>\n"
        "<h2>Parsed YAML Columns</h2>\n"
        "<table>\n"
        "  <tr><th>Column</th><th>Value</th></tr>\n"
        + "\n".join(rows)
        + "\n</table>\n</body></html>"
    )


def main():
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} <file.yaml> [output.html]", file=sys.stderr)
        sys.exit(1)

    input_path = sys.argv[1]
    output_path = sys.argv[2] if len(sys.argv) > 2 else None

    with open(input_path) as f:
        data = yaml.safe_load(f)

    columns = flatten_columns(data)
    html = rows_to_html(columns)

    if output_path:
        with open(output_path, "w") as f:
            f.write(html)
        print(f"Wrote {len(columns)} columns to {output_path}")
    else:
        print(html)


if __name__ == "__main__":
    main()
